import { unstable_cache } from 'next/cache'
import { getAllProducts } from './db'

// Catalog is read-heavy: serve product data from the cache on every request
// instead of re-querying the database. Tagged with "products" so on-demand
// revalidation (e.g. a catalog sync) can refresh it in the background.
export const getCachedProducts = unstable_cache(
  async () => {
    return getAllProducts()
  },
  ['products'],
  {
    tags: ['products'],
    // Keep cached catalog data until it is explicitly invalidated by a sync.
    revalidate: false,
  }
)

