import { revalidateTag } from 'next/cache'
import { getCachedProducts } from '@/lib/products'
import { SyncButton } from './sync-button'

export const metadata = {
  title: 'Admin · Product Catalog',
}

export const dynamic = 'force-static'

export default async function AdminCatalogPage() {
  // Served from the "products" tagged cache; no database query on every request.
  const products = await getCachedProducts()

  // Inline Server Action: triggers a background refresh of the catalog.
  // revalidateTag('products', 'max') uses stale-while-revalidate semantics, so
  // this action returns immediately (the admin keeps working on the stale list)
  // and the "products" tag is refreshed in the background. Any view that shares
  // the "products" tag becomes up to date on subsequent reads.
  async function syncCatalog() {
    'use server'
    // Kick off / mark the upstream ERP/PIM sync as stale. The actual sync work
    // would be dispatched to a job queue here; we don't block the response on it.
    revalidateTag('products', 'max')
  }

  return (
    <main style={{ maxWidth: 720, margin: '0 auto', padding: 24 }}>
      <header
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          gap: 16,
        }}
      >
        <div>
          <h1 style={{ margin: 0 }}>Product Catalog</h1>
          <p style={{ margin: '4px 0 0', color: '#666' }}>
            {products.length} products · cached for fast browsing
          </p>
        </div>
        <form action={syncCatalog}>
          <SyncButton />
        </form>
      </header>

      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: 24 }}>
        <thead>
          <tr style={{ textAlign: 'left', borderBottom: '2px solid #eee' }}>
            <th style={{ padding: 8 }}>ID</th>
            <th style={{ padding: 8 }}>Name</th>
            <th style={{ padding: 8, textAlign: 'right' }}>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id} style={{ borderBottom: '1px solid #eee' }}>
              <td style={{ padding: 8 }}>{product.id}</td>
              <td style={{ padding: 8 }}>{product.name}</td>
              <td style={{ padding: 8, textAlign: 'right' }}>
                ${product.price}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

